
clear; clc;

%% Pilot Insertion reference setup
Nsym = 127;
Ndata = 48;
Nfft = 64;

% This file is generated by your already-verified Pilot_Gen testbench.
polarity = readmatrix('rtl_pilot_polarity.txt');
polarity = polarity(:);

assert(numel(polarity) >= Nsym, ...
    'Need at least 127 pilot polarity samples.');
assert(all(polarity(1:Nsym) == 1 | polarity(1:Nsym) == -1), ...
    'Polarity file must contain only +1 and -1.');

polarity = polarity(1:Nsym);

% Mapper input order expected by Pilot_Insertion
tones = [-26:-22, -20:-8, -6:-1, 1:6, 8:20, 22:26];
assert(numel(tones) == Ndata);

% Signed pilots in standard order
pilotTones = [-21, -7, 7, 21];

% MATLAB stores I and Q as signed Q1.15 integers.
% Generate deterministic, distinguishable mapper values.
allInputWords = zeros(Nsym*Ndata, 1, 'uint32');
expectedWords = zeros(Nsym*Nfft, 1, 'uint32');

for s = 1:Nsym
    % Use different data values for each OFDM symbol.
    n = (s-1)*Ndata + (0:Ndata-1);

    I = int16(round(12000 * sin(2*pi*n/53)));
    Q = int16(round(10000 * cos(2*pi*n/47)));

    % Pack mapper input as {I[15:0], Q[15:0]}.
    for d = 1:Ndata
        wi = uint32(typecast(I(d), 'uint16'));
        wq = uint32(typecast(Q(d), 'uint16'));
        allInputWords((s-1)*Ndata+d) = ...
            bitor(bitshift(wi,16), wq);
    end

    % Start every OFDM symbol with 64 zero bins.
    binsI = zeros(Nfft,1,'int16');
    binsQ = zeros(Nfft,1,'int16');

    % Insert the 48 data subcarriers.
    for d = 1:Ndata
        idx = mod(tones(d),Nfft) + 1;
        binsI(idx) = I(d);
        binsQ(idx) = Q(d);
    end

    % Insert pilots using the sequence from the verified RTL.
    % Standard order [-21,-7,+7,+21] => [Pn,Pn,Pn,-Pn].
    pilotValues = [polarity(s), polarity(s), ...
                   polarity(s), -polarity(s)];

    for p = 1:4
        idx = mod(pilotTones(p),Nfft) + 1;

        if pilotValues(p) == 1
            binsI(idx) = int16(32767);
        else
            binsI(idx) = int16(-32768);
        end

        binsQ(idx) = int16(0);
    end

    % Pack expected output bins in natural order 0..63.
    for b = 1:Nfft
        wi = uint32(typecast(binsI(b), 'uint16'));
        wq = uint32(typecast(binsQ(b), 'uint16'));

        expectedWords((s-1)*Nfft+b) = ...
            bitor(bitshift(wi,16), wq);
    end
end

% Write input stimulus for QuestaSim.
fid = fopen('mapper_input.hex','w');
assert(fid >= 0, 'Cannot create mapper_input.hex.');
for k = 1:numel(allInputWords)
    fprintf(fid,'%08X\n',allInputWords(k));
end
fclose(fid);

% Write MATLAB expected output.
fid = fopen('pilot_expected.hex','w');
assert(fid >= 0, 'Cannot create pilot_expected.hex.');
for k = 1:numel(expectedWords)
    fprintf(fid,'%08X\n',expectedWords(k));
end
fclose(fid);

% Save the polarity sequence used for this run.
fid = fopen('expected_polarity.txt','w');
assert(fid >= 0, 'Cannot create expected_polarity.txt.');
for k = 1:Nsym
    fprintf(fid,'%+d\n',polarity(k));
end
fclose(fid);

fprintf('Generated %d OFDM symbols.\n', Nsym);
fprintf('Mapper input words: %d\n', numel(allInputWords));
fprintf('Expected output bins: %d\n', numel(expectedWords));
fprintf('First 10 polarities:\n');
disp(polarity(1:10).');
